properties.property:
local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local Spawn = require "actions/Spawn"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        local item = require(self.object.properties.item:sub(4, -5))
                        GameState:grantItem(item, 1)
                        self.scene:run(Spawn(BlockPlayer{
                            MessageBox{message="Found a {h "..(item.name).."}!", sfx="levelup"},
                            Do(function() self:permanentRemove() end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Spawn = require "actions/Spawn"
local Do = require "actions/Do"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        self.scene:run(Spawn({
                            self.scene:enterBattle {
                                opponents = {"bug"}
                            },
                            Do(function() self:permanentRemove() end)
                        })
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"
local Wait = require "actions/Wait"
local Spawn = require "actions/Spawn"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()
                        self.scene:run(Spawn(BlockPlayer {
                            Wait(1),
                            Do(function() self.scene.player.state = "thinking" end),
                            MessageBox{message="Sally: Nevermind{p60}, I'm just seeing things."},
                            Do(function()
                                self.scene.player.state = "idleup"
                                self:permanentRemove()
                            end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local MessageBox = require "actions/MessageBox"
local DialogueChoice = require "actions/DialogueChoice"
local Do = require "actions/Do"
local Wait = require "actions/Wait"
local Ease = require "actions/Ease"
local PlayAudio = require "actions/PlayAudio"
local Spawn = require "actions/Spawn"

return function(self)
    return BlockPlayer {
        Do(function() self.scene.player.state = "idleup" end),
        MessageBox{message="Sally: I thought I saw something..."},
        DialogueChoice(
            "Investigate?",
            {
                {"Yes",
                    function(menu)
                        menu:close()

                        local movable1 = self.scene:findLayer("movable1")
                        self.scene:run(Spawn(BlockPlayer {
                            Wait(1),
                            PlayAudio("sfx", "explosion", 1, true),
                            Ease(movable1, "offsety", -8*32, 1),
                            Do(function()
                                self.scene.player.state = "idleup"
                                self:permanentRemove()
                            end)
                        }))
                    end},
                {"No",
                    function(menu)
                        menu:close()
                    end}
            }
        )
    }
end

